import unittest
from candidate import filter_by_prefix


class TestFilterByPrefix(unittest.TestCase):
    def test_normal_case_with_multiple_matches(self):
        result = filter_by_prefix(['apple', 'banana', 'apricot'], 'ap')
        self.assertEqual(result, ['apple', 'apricot'])

    def test_normal_case_with_no_matches(self):
        result = filter_by_prefix(['cat', 'dog', 'fish'], 'b')
        self.assertEqual(result, [])

    def test_empty_input_list_returns_empty(self):
        result = filter_by_prefix([], 'a')
        self.assertEqual(result, [])

    def test_empty_prefix_returns_all_strings(self):
        result = filter_by_prefix(['a', 'b', 'c'], '')
        self.assertEqual(result, ['a', 'b', 'c'])

    def test_prefix_longer_than_any_string(self):
        result = filter_by_prefix(['ab', 'abc'], 'abcd')
        self.assertEqual(result, [])

    def test_case_sensitivity(self):
        result = filter_by_prefix(['Apple', 'apricot'], 'a')
        self.assertEqual(result, ['apricot'])

    def test_unicode_characters(self):
        result = filter_by_prefix(['ábc', 'abc', 'áb'], 'á')
        self.assertEqual(result, ['ábc'])

    def test_input_list_not_modified(self):
        original = ['alpha', 'beta', 'gamma']
        copy = original[:]
        filter_by_prefix(original, 'a')
        self.assertEqual(original, copy)

    def test_generator_input_works(self):
        generator = (x for x in ['alpha', 'beta', 'abacus'])
        result = filter_by_prefix(generator, 'a')
        self.assertEqual(result, ['alpha', 'abacus'])

    def test_tuple_input_works(self):
        result = filter_by_prefix(('alpha', 'beta', 'abacus'), 'a')
        self.assertEqual(result, ['alpha', 'abacus'])

    def test_dict_keys_as_strings_works(self):
        data = {'alpha': 1, 'beta': 2, 'abacus': 3}
        result = filter_by_prefix(data, 'a')
        self.assertEqual(result, ['alpha', 'abacus'])

    def test_none_as_strings_argument_raises_type_error(self):
        with self.assertRaises(TypeError):
            filter_by_prefix(None, 'a')

    def test_non_string_in_list_raises_attribute_error(self):
        with self.assertRaises(AttributeError):
            filter_by_prefix(['apple', 123, 'apricot'], 'a')

    def test_none_as_prefix_raises_type_error(self):
        with self.assertRaises(TypeError):
            filter_by_prefix(['apple', 'banana'], None)

    def test_non_string_prefix_raises_type_error(self):
        with self.assertRaises(TypeError):
            filter_by_prefix(['apple', 'banana'], 1)

    def test_bytes_prefix_raises_type_error(self):
        with self.assertRaises(TypeError):
            filter_by_prefix(['apple', 'banana'], b'a')

    def test_empty_string_in_list_with_empty_prefix(self):
        result = filter_by_prefix(['', 'a', ''], '')
        self.assertEqual(result, ['', 'a', ''])

    def test_prefix_matches_entire_string(self):
        result = filter_by_prefix(['ab', 'abc', 'abcd'], 'ab')
        self.assertEqual(result, ['ab', 'abc', 'abcd'])

    def test_long_prefix_matching_entire_string(self):
        result = filter_by_prefix(['longstring'], 'longstring')
        self.assertEqual(result, ['longstring'])

    def test_multiple_matches_and_order_preserved(self):
        data = ['banana', 'apple', 'apricot', 'avocado']
        result = filter_by_prefix(data, 'a')
        self.assertEqual(result, ['apple', 'apricot', 'avocado'])

    def test_input_with_none_element_raises_attribute_error(self):
        with self.assertRaises(AttributeError):
            filter_by_prefix(['apple', None, 'apricot'], 'a')

    def test_prefix_is_empty_string_returns_all(self):
        result = filter_by_prefix(['x', 'y', 'z'], '')
        self.assertEqual(result, ['x', 'y', 'z'])


if __name__ == "__main__":
    unittest.main()
